const input = $input.first().json;
const topic = input.topic || input.query || input.text || '';

const queries = [
  `${topic} 2026 latest developments`,
  `${topic} best practices guide`,
  `${topic} tools and frameworks comparison`
];

return queries.map((q, i) => ({
  json: {
    query: q,
    topic: topic,
    query_index: i + 1,
    search_depth: i === 0 ? 'deep' : 'standard'
  }
}));

const allResults = $input.all();
let combinedContent = '';
let sources = [];

for (const item of allResults) {
  const results = item.json.results || [];
  for (const r of results) {
    combinedContent += `[Source: ${r.title}]\n${r.content || 'No content'}\n\n`;
    sources.push({ title: r.title, url: r.url, score: r.score || 0 });
  }
}

const seen = new Set();
sources = sources.filter(s => {
  const key = s.url;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

return [{
  json: {
    research_content: combinedContent.substring(0, 15000),
    source_count: sources.length,
    sources: sources,
    topic: allResults[0]?.json?.topic || 'Research'
  }
}];

const aiOutput = $input.first().json.output || $input.first().json.text || '';
const context = $input.first().json;

return [{
  json: {
    topic: context.topic,
    report: aiOutput,
    source_count: context.source_count || 0,
    generated_at: new Date().toISOString(),
    sources: context.sources || [],
    markdown: `# Research Brief: ${context.topic}\n\n${aiOutput}\n\n---\n*Generated by AI Research Agent*`
  }
}];
